arguments.command:
cd /tmp && rm -rf t && cp -r /app t && cd t && autoreconf -fi 2>&1 | grep -v "^libtoolize" | head -20
run(){ n=$1; shift; rm -rf /tmp/b$n /tmp/i$n; mkdir /tmp/b$n; cd /tmp/b$n; /tmp/t/configure --prefix=/opt/p$n "$@" >/dev/null && make -j4 >/dev/null 2>&1 && make check 2>&1 | grep -E "^# (PASS|FAIL)"; make install DESTDIR=/tmp/i$n >/dev/null 2>&1; (cd /tmp/i$n; find . -type f -o -type l | sort); make uninstall DESTDIR=/tmp/i$n >/dev/null 2>&1; find /tmp/i$n -type f -o -type l; }
run 1; run 2 --disable-shared; run 3 --libdir=/opt/p3/lib64 --datarootdir=/opt/d3 --disable-tool

